  splatAdjustmentValidationVersion: 0,
  splatAdjustmentEpoch: 0,
  splatInspectorNonfiniteCache: null,
  splatAdjustmentStats: { requests: 0, renders: 0, staleDropped: 0, yields: 0, lastMs: 0 },
